contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.deposit{value: amount}();

        uint256 creditBefore = c.credit(address(this));
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditAfter = c.credit(address(this));
        uint256 balanceAfter = address(c).balance;

        assert(amount > 0 == !reverted);
        assert(creditBefore == amount);
        assert(!reverted implies (creditAfter == 0 && balanceAfter == balanceBefore - amount));
    }

    receive() external payable {}
}

